package com.ncdex.instrument.controller;
import com.ncdex.instrument.document.Instrument;import com.ncdex.instrument.service.InstrumentService;import jakarta.validation.Valid;import org.springframework.http.HttpStatus;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/instruments") public class InstrumentController {private final InstrumentService service;public InstrumentController(InstrumentService s){service=s;}@GetMapping public List<Instrument> all(@RequestParam(required=false)String q){return q==null||q.isBlank()?service.all():service.search(q);}@GetMapping("/{id}") public Instrument get(@PathVariable String id){return service.get(id);}@PostMapping @ResponseStatus(HttpStatus.CREATED) @PreAuthorize("hasRole('ADMIN')") public Instrument create(@Valid @RequestBody Instrument i){return service.create(i);}@PutMapping("/{id}") @PreAuthorize("hasRole('ADMIN')") public Instrument update(@PathVariable String id,@Valid @RequestBody Instrument i){return service.update(id,i);}@PatchMapping("/{id}/status") @PreAuthorize("hasRole('ADMIN')") public Instrument status(@PathVariable String id,@RequestParam boolean active){return service.setActive(id,active);} }
